const movies = $json.results.slice(0, 3);

return [
  {
    json: {
      results: movies
    }
  }
];

const cast = $json.cast
  .slice(0,3)
  .map(actor => actor.name)
  .join(" • ");

return [{
  json:{
    cast
  }
}];

const director = $json.crew.find(p => p.job === "Director");

return [{
  json:{
    director_id: director.id,
    director: director ? director.name : ""
  }
}];

// Find an official YouTube trailer
let trailer = $json.results.find(
  video => video.site === "YouTube" && video.type === "Trailer"
);

// If no trailer, use a teaser
if (!trailer) {
  trailer = $json.results.find(
    video => video.site === "YouTube" && video.type === "Teaser"
  );
}

return [{
  json: {
    trailer: trailer
      ? `https://www.youtube.com/watch?v=${trailer.key}`
      : ""
  }
}];

